import{_ as t,c as o,o as a,ag as r}from"./chunks/framework.dvv-DFtf.js";const u=JSON.parse('{"title":"Navigation","description":"","frontmatter":{},"headers":[],"relativePath":"navigation.md","filePath":"navigation.md"}'),s={name:"navigation.md"};function i(c,e,l,d,n,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h1><p>Learn how to navigate Kubby efficiently using keyboard shortcuts and UI elements.</p><h2 id="navigation-model" tabindex="-1">Navigation Model <a class="header-anchor" href="#navigation-model" aria-label="Permalink to &quot;Navigation Model&quot;">​</a></h2><p>Kubby uses a hierarchical navigation model:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Context → Namespace → Resource Type → Resource → Detail/Logs/Shell</span></span></code></pre></div><p>You can navigate forward by drilling into resources, and backward using <code>Esc</code>.</p><h2 id="global-navigation" tabindex="-1">Global Navigation <a class="header-anchor" href="#global-navigation" aria-label="Permalink to &quot;Global Navigation&quot;">​</a></h2><p>These controls are available from anywhere in the app:</p><h3 id="context-selector-opt-c" tabindex="-1">Context Selector (<code>Opt+C</code>) <a class="header-anchor" href="#context-selector-opt-c" aria-label="Permalink to &quot;Context Selector (`Opt+C`)&quot;">​</a></h3><p>Switch between Kubernetes contexts (clusters):</p><ol><li>Press <code>Opt+C</code> to open the context selector</li><li>Type to filter available contexts</li><li>Press <code>Enter</code> to select</li><li>The view refreshes with the new context</li></ol><h3 id="namespace-selector-opt-n" tabindex="-1">Namespace Selector (<code>Opt+N</code>) <a class="header-anchor" href="#namespace-selector-opt-n" aria-label="Permalink to &quot;Namespace Selector (`Opt+N`)&quot;">​</a></h3><p>Switch namespaces within the current context:</p><ol><li>Press <code>Opt+N</code> to open the namespace selector</li><li>Type to filter namespaces</li><li>Select &quot;All Namespaces&quot; to view across all namespaces</li><li>Press <code>Enter</code> to select</li></ol><h3 id="resource-type-selector-opt-r" tabindex="-1">Resource Type Selector (<code>Opt+R</code>) <a class="header-anchor" href="#resource-type-selector-opt-r" aria-label="Permalink to &quot;Resource Type Selector (`Opt+R`)&quot;">​</a></h3><p>Switch to a different resource type:</p><ol><li>Press <code>Opt+R</code> to open the resource type selector</li><li>Type to filter (e.g., &quot;deploy&quot;, &quot;pod&quot;, &quot;svc&quot;)</li><li>Press <code>Enter</code> to view that resource type</li></ol><h3 id="quick-resource-switch" tabindex="-1">Quick Resource Switch (<code>:</code>) <a class="header-anchor" href="#quick-resource-switch" aria-label="Permalink to &quot;Quick Resource Switch (`:`)&quot;">​</a></h3><p>k9s-style resource switching:</p><ol><li>Press <code>:</code> to open the command input</li><li>Type the resource type (e.g., <code>pods</code>, <code>deploy</code>, <code>svc</code>)</li><li>Press <code>Enter</code> to switch</li></ol><h2 id="hotbar" tabindex="-1">Hotbar <a class="header-anchor" href="#hotbar" aria-label="Permalink to &quot;Hotbar&quot;">​</a></h2><p>The <strong>hotbar</strong> is a toggle-able sidebar on the right of the resource screens (Resource List, Resource Detail, Log Viewer — it does not appear on the Dashboard). It stores shortcuts to specific screens so you can jump between resource / context / namespace combinations without going through the selectors each time.</p><p>Each saved slot captures a <strong>resource type + context + namespace</strong> (e.g. <code>horizontalpodautoscalers @ dev / my-namespace</code>).</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Opt+H</code></td><td>Show / hide the hotbar</td></tr><tr><td><code>Opt+1</code> … <code>Opt+9</code></td><td>Jump to the first nine saved slots</td></tr></tbody></table><ul><li><strong>Add:</strong> open the hotbar and click <strong>Add current screen</strong> to pin the screen you are on. Duplicate screens are ignored, and the containers view can&#39;t be pinned (it needs a parent pod).</li><li><strong>Jump:</strong> click a slot (or press <code>Opt+1</code>–<code>Opt+9</code>) to switch the current view to that screen. It replaces where you are in the breadcrumb instead of stacking, so the depth never grows; <code>Esc</code> / Back then goes up one level from there.</li><li><strong>Rename:</strong> hover a slot and click the pencil (<code>✎</code>) to give it a custom name.</li><li><strong>Remove:</strong> hover a slot and click <code>×</code>.</li></ul><p>Saved slots and the open / collapsed state persist across restarts. Slots whose context is no longer in your config are dimmed.</p><p>The sidebar also has a <strong>Read-only toggle</strong> at the top. It starts from your config&#39;s <code>readOnly</code> value; when on, it disables mutating actions (Edit, Scale, Delete, Rolling Restart, Port-forward, Run) across all resource screens. It is a temporary, session-only switch — it never edits your config file and resets to the config value when you restart Kubby. When the hotbar is collapsed, the same toggle appears as an <strong>RO</strong> button on the rail.</p><h2 id="view-navigation" tabindex="-1">View Navigation <a class="header-anchor" href="#view-navigation" aria-label="Permalink to &quot;View Navigation&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>The Dashboard shows multiple resource tables. Navigate between them:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>Move to next table</td></tr><tr><td><code>Shift+Tab</code></td><td>Move to previous table</td></tr><tr><td><code>←</code> <code>→</code></td><td>Navigate columns</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Navigate rows</td></tr><tr><td><code>Enter</code></td><td>Open selected resource</td></tr></tbody></table><h3 id="resource-list" tabindex="-1">Resource List <a class="header-anchor" href="#resource-list" aria-label="Permalink to &quot;Resource List&quot;">​</a></h3><p>Single resource type view with full-width table:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Navigate resources</td></tr><tr><td><code>Enter</code></td><td>Primary action (varies by type)</td></tr><tr><td><code>J</code></td><td>Jump to related resources</td></tr><tr><td><code>Esc</code></td><td>Go back to Dashboard</td></tr></tbody></table><h3 id="resource-detail" tabindex="-1">Resource Detail <a class="header-anchor" href="#resource-detail" aria-label="Permalink to &quot;Resource Detail&quot;">​</a></h3><p>Detailed view of a single resource:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Y</code> / <code>T</code> / <code>J</code></td><td>Switch view mode</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Scroll content</td></tr><tr><td><code>Page Up</code> / <code>Page Down</code></td><td>Fast scroll</td></tr><tr><td><code>Esc</code></td><td>Go back</td></tr></tbody></table><h3 id="log-viewer" tabindex="-1">Log Viewer <a class="header-anchor" href="#log-viewer" aria-label="Permalink to &quot;Log Viewer&quot;">​</a></h3><p>Streaming log view:</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Scroll (when auto-scroll off)</td></tr><tr><td><code>A</code></td><td>Toggle auto-scroll</td></tr><tr><td><code>C</code></td><td>Copy logs</td></tr><tr><td><code>D</code></td><td>Open the download menu</td></tr><tr><td><code>Esc</code></td><td>Close the download menu, then close the log viewer</td></tr></tbody></table><p><strong>Downloading logs.</strong> Pressing <code>D</code> (or clicking <strong>Download</strong>) opens a small menu with two choices, both saved to <code>~/Downloads</code>:</p><ul><li><strong>All logs</strong> (<code>A</code>) — fetches the complete log for the container from the cluster (not just what is loaded on screen).</li><li><strong>Visible logs</strong> (<code>V</code>) — saves only what is currently loaded in the viewer (the filtered lines when a text filter is active).</li></ul><p>Tick <strong>Show logs from previous terminated container</strong> (<code>P</code>) to have <strong>All logs</strong> also include the previously terminated container&#39;s log (when one exists). While the menu is open <code>Esc</code> closes it.</p><h2 id="back-navigation" tabindex="-1">Back Navigation <a class="header-anchor" href="#back-navigation" aria-label="Permalink to &quot;Back Navigation&quot;">​</a></h2><p>Press <code>Esc</code> to go back one level:</p><ul><li>From Resource Detail → Resource List</li><li>From Log Viewer → Previous view</li><li>From Resource List → Dashboard</li><li>Closes any open modal or dialog</li></ul><h2 id="refresh" tabindex="-1">Refresh <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;Refresh&quot;">​</a></h2><p>Press <code>Ctrl+R</code> to refresh the current view:</p><ul><li>Dashboard: Refreshes all resource tables</li><li>Resource List: Reloads the resource list</li><li>Resource Detail: Fetches latest resource state</li><li>Log Viewer: Restarts the log stream</li></ul><h2 id="filter-input" tabindex="-1">Filter Input <a class="header-anchor" href="#filter-input" aria-label="Permalink to &quot;Filter Input&quot;">​</a></h2><p>Most views have a filter input for searching:</p><ol><li>Start typing to filter by name</li><li>Filter applies instantly</li><li>Press <code>Esc</code> to clear the filter</li><li>Works across all visible resources</li></ol><h2 id="navigation-flow-examples" tabindex="-1">Navigation Flow Examples <a class="header-anchor" href="#navigation-flow-examples" aria-label="Permalink to &quot;Navigation Flow Examples&quot;">​</a></h2><h3 id="view-pod-logs" tabindex="-1">View Pod Logs <a class="header-anchor" href="#view-pod-logs" aria-label="Permalink to &quot;View Pod Logs&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dashboard → Select Deployment → Enter (view pods) → Select Pod → L (logs)</span></span></code></pre></div><h3 id="scale-a-deployment" tabindex="-1">Scale a Deployment <a class="header-anchor" href="#scale-a-deployment" aria-label="Permalink to &quot;Scale a Deployment&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dashboard → Select Deployment → S (scale) → Enter count → Enter (confirm)</span></span></code></pre></div><h3 id="port-forward-to-a-service" tabindex="-1">Port Forward to a Service <a class="header-anchor" href="#port-forward-to-a-service" aria-label="Permalink to &quot;Port Forward to a Service&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Opt+R → type &quot;svc&quot; → Enter → Select Service → F (port-forward) → Configure → Enter</span></span></code></pre></div><h3 id="jump-to-related-resources" tabindex="-1">Jump to Related Resources <a class="header-anchor" href="#jump-to-related-resources" aria-label="Permalink to &quot;Jump to Related Resources&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Select Deployment → J (jump) → Select &quot;Pods&quot; → View matching pods</span></span></code></pre></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Staying Oriented</p><p>The header always shows your current context, namespace, and resource type so you know where you are.</p></div><div class="tip custom-block"><p class="custom-block-title">Quick Return to Dashboard</p><p>From any view, press <code>Esc</code> repeatedly to return to the Dashboard.</p></div><div class="tip custom-block"><p class="custom-block-title">Filtering is Fast</p><p>The filter input searches as you type with no delay. Use it liberally to find resources quickly.</p></div>',65)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
